/** Root of the census hierarchy: a leaf carries a `value`, a branch carries `children`. */
export type Data = { name: string; value?: number; children?: Data[] };

type Cell = d3.HierarchyRectangularNode<Data>;

const FONT_SIZE = 10;
const LABEL_INSET = 3;

const format = d3.format(',d');

function pathOf(node: Cell): string {
  return node
    .ancestors()
    .map((a) => a.data.name)
    .reverse()
    .join(' / ');
}

/** The zone a leaf belongs to, for coloring by top-level category rather than immediate tank. */
function zoneOf(node: Cell): Cell {
  let ancestor = node;
  while (ancestor.depth > 1) ancestor = ancestor.parent as Cell;
  return ancestor;
}

export default function Treemap({ data = aquariumCensus, width }: { data?: Data; width: number }) {
  const height = width;
  const clipBase = `treemap-clip-${useId().replace(/:/g, '')}`;

  const root = useMemo(
    () =>
      d3
        .treemap<Data>()
        .size([width, height])
        .padding(1)
        .round(true)(
        d3
          .hierarchy(data)
          .sum((d) => d.value ?? 0)
          .sort((a, b) => (b.value ?? 0) - (a.value ?? 0))
      ),
    [data, width, height]
  );

  const color = useMemo(
    () =>
      d3.scaleOrdinal<string, string>(
        (root.children ?? []).map((d) => d.data.name),
        d3.schemeTableau10
      ),
    [root]
  );

  const leaves = useMemo(() => root.leaves(), [root]);

  if (width === 0) return null;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Treemap of an aquarium's specimen census, one rectangle per species colored by habitat zone"
      fontSize={FONT_SIZE}
    >
      {leaves.map((d, i) => {
        const cellWidth = d.x1 - d.x0;
        const cellHeight = d.y1 - d.y0;
        const fill = color(zoneOf(d).data.name);
        const value = format(d.value ?? 0);
        const words = [...d.data.name.split(' '), value];
        const clipId = `${clipBase}-${i}`;
        const showLabel = cellWidth > LABEL_INSET * 2 && cellHeight > 1.1 * FONT_SIZE;

        return (
          <g key={pathOf(d)} transform={`translate(${d.x0},${d.y0})`}>
            <title>{`${pathOf(d)}\n${value} specimens`}</title>
            <clipPath id={clipId}>
              <rect width={cellWidth} height={cellHeight} />
            </clipPath>
            <rect width={cellWidth} height={cellHeight} fill={fill} fillOpacity={0.6} />
            {showLabel && (
              <text clipPath={`url(#${clipId})`} fill="var(--text)">
                {words.map((word, wordIndex) => (
                  <tspan
                    key={wordIndex}
                    x={LABEL_INSET}
                    y={`${1.1 + wordIndex * 0.9 + (wordIndex === words.length - 1 ? 0.3 : 0)}em`}
                    fillOpacity={wordIndex === words.length - 1 ? 0.7 : undefined}
                  >
                    {word}
                  </tspan>
                ))}
              </text>
            )}
          </g>
        );
      })}
    </svg>
  );
}
